'use client';
import { Plus } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import React, { useState } from 'react';

const tabs = [
  {
    title: 'How do UI components improve UX?',
    description:
      'UI components can improve UX by providing familiar, consistent interactions that make it easy for users to navigate and interact with an application.',
    imageUrl:
      'https://images.unsplash.com/photo-1709949908058-a08659bfa922?q=80&w=1200&auto=format',
  },
  {
    title: 'Common UI component design challenges?',
    description:
      'Some common challenges include maintaining consistency across different devices and screen sizes, ensuring compatibility with various browsers and assistive technologies, and balancing flexibility with ease of use.',
    imageUrl:
      'https://images.unsplash.com/photo-1548192746-dd526f154ed9?q=80&w=1200&auto=format',
  },
  {
    title: 'Ensuring UI component responsiveness?',
    description:
      'Developers can ensure the responsiveness of UI components by using techniques such as fluid layouts, flexible grids, and media queries to adapt the components to different screen sizes and orientations.',
    imageUrl:
      'https://images.unsplash.com/photo-1693581176773-a5f2362209e6?q=80&w=1200&auto=format',
  },
];

type TabItem = {
  title: string;
  description: string;
  imageUrl: string;
};

function SingleLayout() {
  const [activeIndex, setActiveIndex] = useState<number | null>(0);
  const [activeItem, setActiveItem] = useState<TabItem | undefined>(tabs[0]);

  const handleClick = (index: number) => {
    const isCurrentActive = activeIndex === index;

    if (isCurrentActive) {
      // If clicking the active tab, close it and clear the active item
      setActiveIndex(null);
      setActiveItem(undefined);
    } else {
      // If clicking a new tab, open it and set the active item cleanly using index matching
      setActiveIndex(index);
      setActiveItem(tabs[index]);
    }
  };

  return (
    <div className='container mx-auto pb-10 pt-2'>
      <h2 className='uppercase text-center text-4xl font-bold pt-2 pb-4'>
        FAQ
      </h2>
      <div className='h-fit border rounded-lg p-2 dark:bg-[#111111] bg-[#F2F2F2]'>
        {tabs.map((tab, index) => {
          const isOpen = activeIndex === index;

          return (
            <motion.div
              key={tab.title}
              className={`overflow-hidden ${index !== tabs.length - 1 ? 'border-b' : ''}`}
            >
              {/* Accessible button - handle click here instead of the wrapping div */}
              <button
                className={`p-3 px-2 w-full cursor-pointer sm:text-base text-xs items-center transition-all font-semibold text-foreground   flex gap-2
               `}
              >
                <Plus
                  className={`${
                    activeIndex === index ? 'rotate-45' : 'rotate-0 '
                  } transition-transform ease-in-out w-5 h-5  text-muted-foreground`}
                />
                {tab.title}
              </button>

              <AnimatePresence mode='sync'>
                {isOpen && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: 'auto', opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{
                      duration: 0.3,
                      ease: 'easeInOut',
                    }}
                  >
                    <p
                      className={`text-foreground p-3 xl:text-base sm:text-sm text-xs pt-0 w-[90%]`}
                    >
                      {tab.description}
                    </p>
                  </motion.div>
                )}
              </AnimatePresence>
            </motion.div>
          );
        })}
      </div>
    </div>
  );
}

export default SingleLayout;

'use client';

import { Accordion as SDKAccordion, AccordionItem as SDKItem, AccordionHeader as SDKHeader, AccordionTrigger as SDKTrigger, AccordionPanel as SDKPanel } from '@ui-sdk/react/accordion';
import { cn } from '@/lib/utils';
import { ChevronDown } from 'lucide-react';
import { AnimatePresence, motion } from 'motion/react';
import React, { type ReactNode } from 'react';

/**
 * Interface for AccordionContext values
 */
interface AccordionContextType {
  /**
   * Whether the accordion item is active
   */
  isActive?: boolean;
}

/**
 * Context for accordion components
 */
const AccordionContext = React.createContext<AccordionContextType>({});
/**
 * Hook to use the accordion context
 */
const useAccordion = () => React.useContext(AccordionContext);

/**
 * Container component for accordion items
 */
export function AccordionContainer({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={cn('grid grid-cols-2 gap-1', className)}>{children}</div>;
}

/**
 * Wrapper component for accordion items
 */
export function AccordionWrapper({ children }: { children: ReactNode }) {
  return <div>{children}</div>;
}

/**
 * Interface for Accordion props
 */
interface AccordionProps {
  /**
   * Children components
   */
  children: ReactNode;
  /**
   * Whether multiple items can be active at the same time
   */
  multiple?: boolean;
  /**
   * Default active index
   */
  defaultValue?: string | string[];
}

/**
 * Accordion component
 */
export function Accordion({ children, multiple, defaultValue }: AccordionProps) {
  const initial = multiple ? (Array.isArray(defaultValue) ? defaultValue : []) : typeof defaultValue === 'string' ? [defaultValue] : [];
  const [openValues, setOpenValues] = React.useState(initial);

  return (
    <SDKAccordion multiple={multiple} collapsible value={openValues} onValueChange={setOpenValues} render={<div className='contents' />}>
      {React.Children.map(children, (child) => {
        if (!React.isValidElement(child)) return null;
        const { value } = child.props as { value: string };
        return (
          <AccordionContext.Provider value={{ isActive: openValues.includes(value) }}>
            {child}
          </AccordionContext.Provider>
        );
      })}
    </SDKAccordion>
  );
}

/**
 * Interface for AccordionItem props
 */
interface AccordionItemProps {
  /**
   * Children components
   */
  children: ReactNode;
  /**
   * Value of the accordion item
   */
  value: string;
  className?: string;
}

/**
 * Accordion item component
 */
export function AccordionItem({ children, value, className }: AccordionItemProps) {
  const { isActive } = useAccordion();

  return (
    <SDKItem
      value={value}
      data-active={isActive || undefined}
      className={cn(
        'rounded-lg overflow-hidden mb-2 group border',
        className
      )}
    >
      {children}
    </SDKItem>
  );
}

/**
 * Interface for AccordionHeader props
 */
interface AccordionHeaderProps {
  /**
   * Children components
   */
  children: ReactNode;
  /**
   * Icon component
   */
  customIcon?: boolean;
  className?: string;
}

/**
 * Accordion header component
 */
export function AccordionHeader({ children, customIcon, className }: AccordionHeaderProps) {
  const { isActive } = useAccordion();

  return (
    <SDKHeader className='contents'>
    <SDKTrigger
      render={<motion.button />}
      type='button'
      data-active={isActive || undefined}
      className={cn(
        'p-4 cursor-pointer w-full transition-all font-semibold text-muted-foreground data-active:text-foreground data-active:bg-muted hover:bg-secondary hover:text-foreground flex justify-between gap-2 items-center text-left',
        className
      )}
    >
      {children}
      {!customIcon && (
        <ChevronDown
          className={cn(
            'transition-transform shrink-0 text-muted-foreground',
            isActive ? 'rotate-180' : 'rotate-0'
          )}
          aria-hidden='true'
        />
      )}
    </SDKTrigger>
    </SDKHeader>
  );
}
/**
 * Interface for AccordionPanel props
 */
interface AccordionPanelProps {
  /**
   * Children components
   */
  children: ReactNode;
  /**
   * className
   */
  className?: string;
  /**
   * article className
   */
  articleClassName?: string;
}

/**
 * Accordion panel component
 */
export function AccordionPanel({ children, className, articleClassName }: AccordionPanelProps) {
  const { isActive } = useAccordion();

  return (
    <AnimatePresence initial={true}>
      {isActive && (
        <SDKPanel
          render={<motion.div
            initial={{ height: 0, overflow: 'hidden' }}
            animate={{ height: 'auto', overflow: 'hidden' }}
            exit={{ height: 0 }}
            transition={{ type: 'spring', duration: 0.3, bounce: 0 }}
          />}
          data-active={isActive || undefined}
          className={cn(
            'bg-secondary px-2 data-active:bg-muted text-foreground',
            className
          )}
        >
          <motion.div
            initial={{ clipPath: 'polygon(0 0, 100% 0, 100% 0, 0 0)' }}
            animate={{ clipPath: 'polygon(0 0, 100% 0, 100% 100%, 0% 100%)' }}
            exit={{
              clipPath: 'polygon(0 0, 100% 0, 100% 0, 0 0)',
            }}
            transition={{
              type: 'spring',
              duration: 0.4,
              bounce: 0,
            }}
            className={cn('px-3 bg-transparent pb-4 space-y-2', articleClassName)}
          >
            {children}
          </motion.div>
        </SDKPanel>
      )}
    </AnimatePresence>
  );
}
